css:
.pks4-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.pks4-root,.pks4-root *,.pks4-root *::before,.pks4-root *::after{box-sizing:border-box}
.pks4-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.pks4-root img{display:block;border:0;max-width:none}
.pks4-root [hidden]{display:none!important}
.pks4-root .nS4_1_9601{align-content:stretch;display:flex;gap:13px;align-items:center;position:relative;flex-shrink:0}
.pks4-root .nS4_1_9602{grid-template-columns:max-content;grid-template-rows:max-content;display:inline-grid;line-height:0;place-items:start;position:relative;flex-shrink:0}
.pks4-root .nS4_1_9603{grid-column:1;height:41.513px;margin-left:0;margin-top:0;position:relative;grid-row:1;width:41.516px}
.pks4-root .x400165{position:absolute;inset:0 0 -0.47% -0.47%}
.pks4-root .x400166{display:block;max-width:none;width:100%;height:100%}
.pks4-root .nS4_1_9607{grid-column:1;height:22.084px;margin-left:8.2px;margin-top:9.72px;position:relative;grid-row:1;width:27.092px}
.pks4-root .x400167{position:absolute;display:block;inset:0;max-width:none;width:100%;height:100%}
.pks4-root .nS4_1_9609{word-break:break-word;font-family:"Pretendard","Pretendard Variable","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:600;line-height:35px;font-style:normal;position:relative;flex-shrink:0;color:var(--wa-danger, #ff1a40);font-size:29.12px;letter-spacing:0.5824px;white-space:nowrap;width:136px}
.pks4-root[data-theme="light"]{background:var(--wa-bg, #eef2f7);color:var(--wa-text, #0e1a2b)}
.pks4-root[data-theme="light"] [data-name="Background"] > img{filter:invert(1) hue-rotate(180deg) saturate(0.4) brightness(1.05);opacity:0.5}
.pks4-root[data-theme="light"] [data-name="Building Image"] img{filter:saturate(0.92) brightness(0.98)}
.pks4-root[data-theme="light"] [data-name="Floor Plan"] img{filter:invert(1) hue-rotate(180deg) saturate(0.55) brightness(1.04)}
.pks4-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
.pks4-root[data-theme="light"] .nS4_1_9609{color:var(--wa-danger, #a90420)}
